edits.to:
/* First paint: defender below, shooter at the peak; JS adds only scroll deltas. */
--v3-defender-rise-y: 0px;
--v3-shooter-drop-y: 0px;

overflow: clip; z-index: 20; pointer-events: none;
/* Dissolve the athletes' legs before the hard section boundary. */
-webkit-mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 185px), transparent calc(100% - 22px));
mask-image: linear-gradient(to bottom, #000 0%, #000 calc(100% - 185px), transparent calc(100% - 22px));
